477	func (rw *responseWriter) Close() error {
478		// didn't write, probably head request
479		if !rw.wroteHeader {
480			cl, err := strconv.Atoi(rw.Header().Get("Content-Length"))
481			if err == nil && cl > rw.config.MinLength {
482				rw.init()
483			}
484	
485			// issue #5059, don't write status code if not set explicitly.
486			if rw.statusCode != 0 {
487				rw.ResponseWriter.WriteHeader(rw.statusCode)
488			}
489			rw.wroteHeader = true
490		}
491	
492		var err error
493		if rw.w != nil {
494			err = rw.w.Close()
495			rw.w.Reset(nil)
496			rw.config.writerPools[rw.encodingName].Put(rw.w)
497			rw.w = nil
498		}
499		return err
500	}
