507	// init should be called before we write a response, if rw.buf has contents.
508	func (rw *responseWriter) init() {
509		// Don't initialize encoder for responses that must not be encoded.
510		if rw.disabled {
511			return
512		}
513	
514		hdr := rw.Header()
515	
516		if hdr.Get("Content-Encoding") == "" && isEncodeAllowed(hdr) &&
517			rw.config.Match(rw) {
518			rw.w = rw.config.writerPools[rw.encodingName].Get().(Encoder)
519			rw.w.Reset(rw.ResponseWriter)
520			hdr.Del("Content-Length") // https://github.com/golang/go/issues/14975
521			hdr.Set("Content-Encoding", rw.encodingName)
522			if !hasVaryValue(hdr, "Accept-Encoding") {
523				hdr.Add("Vary", "Accept-Encoding")
524			}
525			hdr.Del("Accept-Ranges") // we don't know ranges for dynamically-encoded content
526	
527			// strong ETags need to be distinct depending on the encoding ("selected representation")
528			// see RFC 9110 section 8.8.3.3:
529			// https://www.rfc-editor.org/rfc/rfc9110.html#name-example-entity-tags-varying
530			// I don't know a great way to do this... how about appending? That's a neat trick!
531			// (We have to strip the value we append from If-None-Match headers before
532			// sending subsequent requests back upstream, however, since upstream handlers
533			// don't know about our appending to their Etag since they've already done their work)
534			if etag := hdr.Get("Etag"); etag != "" && !strings.HasPrefix(etag, "W/") {
535				etag = fmt.Sprintf(`%s-%s"`, strings.TrimSuffix(etag, `"`), rw.encodingName)
536				hdr.Set("Etag", etag)
537			}
538		}
539	}
