541	func hasVaryValue(hdr http.Header, target string) bool {
542		for _, vary := range hdr.Values("Vary") {
543			for val := range strings.SplitSeq(vary, ",") {
544				if strings.EqualFold(strings.TrimSpace(val), target) {
545					return true
546				}
547			}
548		}
549		return false
550	}
