552	// AcceptedEncodings returns the list of encodings that the
553	// client supports, in descending order of preference.
554	// The client preference via q-factor and the server
555	// preference via Prefer setting are taken into account. If
556	// the Sec-WebSocket-Key header is present then non-identity
557	// encodings are not considered. See
558	// http://www.w3.org/Protocols/rfc2616/rfc2616-sec14.html.
559	func AcceptedEncodings(r *http.Request, preferredOrder []string) []string {
560		acceptEncHeader := r.Header.Get("Accept-Encoding")
561		if acceptEncHeader == "" {
562			return []string{}
563		}
564		websocketKey := r.Header.Get("Sec-Websocket-Key")
565	
566		prefs := make([]encodingPreference, 0, strings.Count(acceptEncHeader, ",")+1)
567	
568		for accepted := range strings.SplitSeq(acceptEncHeader, ",") {
569			encName, params, found := strings.Cut(accepted, ";")
570			encName = strings.ToLower(strings.TrimSpace(encName))
