const (
	streamResultCompleted       = "completed"        // both directions ended cleanly
	streamResultError           = "error"            // a copy error ended the stream
	streamResultTimeout         = "timeout"          // stream_timeout elapsed
	streamResultClosed          = "closed"           // closed by a config unload or shutdown
	streamResultUpstreamRemoved = "upstream_removed" // upstream removed by a reload (detached streams)
)

// Directions for streamMetrics.bytes.
const (
	streamDirToBackend   = "to_backend"
	streamDirFromBackend = "from_backend"
)

// streamMetrics are the collectors for upgraded streams. They are created
// once per process, so streams that outlive the config that started them
// keep accounting on the same collectors; they are added to the metrics
// registry of each config by registerStreamMetrics.
var streamMetrics = struct {
	active   prometheus.Gauge
	closed   *prometheus.CounterVec
	duration prometheus.Histogram
	bytes    *prometheus.CounterVec
}{
	active: prometheus.NewGauge(prometheus.GaugeOpts{
		Namespace: "caddy",
		Subsystem: "reverse_proxy",
		Name:      "streams_active",
		Help:      "Number of upgraded streams (e.g. WebSockets) currently open.",
	}),
	closed: prometheus.NewCounterVec(prometheus.CounterOpts{
		Namespace: "caddy",
		Subsystem: "reverse_proxy",
		Name:      "streams_closed_total",
		Help:      "Number of upgraded streams that were closed, by result.",
	}, []string{"result"}),
	duration: prometheus.NewHistogram(prometheus.HistogramOpts{
		Namespace: "caddy",
		Subsystem: "reverse_proxy",
		Name:      "stream_duration_seconds",
		Help:      "Time upgraded streams were open.",
		Buckets:   []float64{1, 10, 60, 300, 1800, 3600, 21600, 86400},
	}),
	bytes: prometheus.NewCounterVec(prometheus.CounterOpts{
		Namespace: "caddy",
		Subsystem: "reverse_proxy",
		Name:      "stream_bytes_total",
		Help:      "Bytes copied through upgraded streams, by direction relative to the backend.",
	}, []string{"direction"}),
}

// registerStreamMetrics adds the stream collectors to registry. Registering
// them again (the same registry on a config reload) is not an error.
func registerStreamMetrics(registry *prometheus.Registry) error {
	for _, c := range []prometheus.Collector{
		streamMetrics.active, streamMetrics.closed, streamMetrics.duration, streamMetrics.bytes,
	} {
		if err := registry.Register(c); err != nil {
			var are prometheus.AlreadyRegisteredError
			if !errors.As(err, &are) {
				return err
			}
		}
	}
	return nil
}

