// stream accounts for one upgraded stream. It is counted as active from
// its creation until finish is first called, whichever of the several
// paths that can end a stream (a copy error, a timeout, a config unload,
// the removal of its upstream) gets there first.
type stream struct {
	upstream string
	start    time.Time

	toBackend, fromBackend atomic.Int64

	once sync.Once
	// onFinish, if set, is called by the first finish with the final numbers.
	onFinish func(result string, duration time.Duration, toBackend, fromBackend int64)
	// closeFn closes both connections of a detached stream.
	closeFn func()
}

func newStream(upstream string) *stream {
	streamMetrics.active.Inc()
	return &stream{upstream: upstream, start: time.Now()}
}

// finish accounts the stream as closed with the given result, and reports
// whether this call was the one that did. Later calls do nothing. It is
// safe to call on a nil stream.
func (s *stream) finish(result string) bool {
	if s == nil {
		return false
	}
	first := false
	s.once.Do(func() {
		first = true
		duration := time.Since(s.start)
		streamMetrics.active.Dec()
		streamMetrics.closed.WithLabelValues(result).Inc()
		streamMetrics.duration.Observe(duration.Seconds())
		if s.onFinish != nil {
			s.onFinish(result, duration, s.toBackend.Load(), s.fromBackend.Load())
		}
	})
	return first
}

// terminate accounts the stream as closed with the given result, then
// closes its connections, which ends the copiers.
func (s *stream) terminate(result string) {
	s.finish(result)
	s.closeFn()
}

// counted returns dst wrapped to count the bytes written to it on s in the
// given direction (and in the metrics). A nil stream counts nothing.
func (s *stream) counted(dst io.Writer, direction string) io.Writer {
	if s == nil {
		return dst
	}
	n := &s.toBackend
	if direction == streamDirFromBackend {
		n = &s.fromBackend
	}
	return &countingWriter{Writer: dst, n: n, metric: streamMetrics.bytes.WithLabelValues(direction)}
}

// countingWriter counts the bytes written through it. Wrapping hides any
// io.ReaderFrom of the destination, which is fine for stream traffic.
type countingWriter struct {
	io.Writer
	n      *atomic.Int64
	metric prometheus.Counter
}

func (w *countingWriter) Write(p []byte) (int, error) {
	n, err := w.Writer.Write(p)
	w.n.Add(int64(n))
	w.metric.Add(float64(n))
	return n, err
}

// streamUpstream returns the key of the upstream req is proxied to, or
// the empty string if it is not known.
func streamUpstream(req *http.Request) string {
	if di, ok := GetDialInfo(req.Context()); ok && di.Upstream != nil {
		return di.Upstream.String()
	}
	return ""
}

// streamFinishLogger returns the function that logs the close of the
// stream for req. The loggers are resolved now, since the function runs
// when the stream ends, possibly after the config that started it is gone.
// The close is logged to the access loggers of the request if it has any,
// so that it shows up in the access log, and otherwise to the handler's logger.
func (h *Handler) streamFinishLogger(req *http.Request) func(string, time.Duration, int64, int64) {
	loggers := []*zap.Logger{h.logger}
	if srv, ok := req.Context().Value(caddyhttp.ServerCtxKey).(*caddyhttp.Server); ok {
		if access := srv.AccessLoggers(req); len(access) > 0 {
			loggers = access
		}
	}
