// upgradedStream runs an upgrade through a handler against a real backend
// and returns the handler and both ends of the established stream.
func upgradedStream(t *testing.T, upgrade string, configure func(h *Handler)) (h *Handler, cli, srv *net.TCPConn) {
	t.Helper()

	srvc := make(chan *net.TCPConn, 1)
	backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		conn, _, err := http.NewResponseController(w).Hijack()
		if err != nil {
			t.Errorf("backend hijack failed: %v", err)
			return
		}
		tcp := conn.(*net.TCPConn)
		if _, err := io.WriteString(tcp, "HTTP/1.1 101 Switching Protocols\r\nConnection: Upgrade\r\nUpgrade: "+upgrade+"\r\n\r\n"); err != nil {
			tcp.Close()
			t.Errorf("backend upgrade write failed: %v", err)
			return
		}
		srvc <- tcp
	}))
	t.Cleanup(backend.Close)

	h = minimalHandler(0, &Upstream{Host: new(Host), Dial: backend.Listener.Addr().String()})
	h.connections = make(map[io.ReadWriteCloser]openConnection)
	h.connectionsMu = new(sync.Mutex)
	configure(h)

	frontend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r = r.WithContext(context.WithoutCancel(r.Context()))
		_ = h.ServeHTTP(w, prepareTestRequest(r), caddyhttp.HandlerFunc(func(http.ResponseWriter, *http.Request) error {
			return nil
		}))
	}))
	t.Cleanup(frontend.Close)

	frontendURL, err := url.Parse(frontend.URL)
	if err != nil {
		t.Fatal(err)
	}
	addr, err := net.ResolveTCPAddr("tcp", frontendURL.Host)
	if err != nil {
		t.Fatal(err)
	}
	cli, err = net.DialTCP("tcp", nil, addr)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { cli.Close() })

	req, _ := http.NewRequest(http.MethodGet, frontend.URL, nil)
	req.Header.Set("Connection", "Upgrade")
	req.Header.Set("Upgrade", upgrade)
	if err := req.Write(cli); err != nil {
		t.Fatal(err)
	}
	resp, err := http.ReadResponse(bufio.NewReader(cli), &http.Request{Method: http.MethodGet})
	if err != nil {
		t.Fatalf("failed to read upgrade response: %v", err)
	}
	if resp.StatusCode != http.StatusSwitchingProtocols {
		t.Fatalf("status = %d, want 101", resp.StatusCode)
	}

	select {
	case srv = <-srvc:
	case <-time.After(5 * time.Second):
		t.Fatal("timed out waiting for the backend connection")
	}
	t.Cleanup(func() { srv.Close() })
	return h, cli, srv
}

func expectRead(t *testing.T, conn *net.TCPConn, msg string) {
	t.Helper()
	_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	b := make([]byte, len(msg))
	if _, err := io.ReadFull(conn, b); err != nil {
		t.Fatalf("failed to read %q: %v", msg, err)
	}
	if string(b) != msg {
		t.Fatalf("got %q, want %q", b, msg)
	}
}

func expectEOF(t *testing.T, conn *net.TCPConn) []byte {
	t.Helper()
	_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	b, err := io.ReadAll(conn)
	if err != nil && !errors.Is(err, io.EOF) && !strings.Contains(err.Error(), "reset") && !strings.Contains(err.Error(), "aborted") {
		t.Fatalf("expected the stream to be closed, got %v", err)
	}
	return b
}

func TestUpgradedStreamResults(t *testing.T) {
	switch runtime.GOOS {
	case "plan9", "js", "wasip1":
		t.Skipf("not supported on %s", runtime.GOOS)
	}

	t.Run("completed with bytes", func(t *testing.T) {
		activeBefore := streamsActive(t)
		completedBefore := streamsClosed(t, streamResultCompleted)
		toBefore, fromBefore := streamBytes(t, streamDirToBackend), streamBytes(t, streamDirFromBackend)

		_, cli, srv := upgradedStream(t, "foo", func(*Handler) {})
		if got := streamsActive(t); got != activeBefore+1 {
			t.Errorf("active streams = %v, want %v", got, activeBefore+1)
		}
		if _, err := cli.Write([]byte("hello")); err != nil {
			t.Fatal(err)
		}
		expectRead(t, srv, "hello")
		if _, err := srv.Write([]byte("world!!")); err != nil {
			t.Fatal(err)
		}
		expectRead(t, cli, "world!!")
		_ = cli.CloseWrite()
		_ = srv.CloseWrite()

		waitUntil(t, "stream to complete", func() bool { return streamsClosed(t, streamResultCompleted) == completedBefore+1 })
		if got := streamsActive(t); got != activeBefore {
			t.Errorf("active streams = %v after close, want %v", got, activeBefore)
		}
		if got := streamBytes(t, streamDirToBackend) - toBefore; got != 5 {
			t.Errorf("bytes to backend moved by %v, want 5", got)
		}
		if got := streamBytes(t, streamDirFromBackend) - fromBefore; got != 7 {
			t.Errorf("bytes from backend moved by %v, want 7", got)
		}
	})

	t.Run("timeout", func(t *testing.T) {
		before := streamsClosed(t, streamResultTimeout)
		_, cli, _ := upgradedStream(t, "foo", func(h *Handler) { h.StreamTimeout = caddy.Duration(50 * time.Millisecond) })
		expectEOF(t, cli)
		waitUntil(t, "stream to time out", func() bool { return streamsClosed(t, streamResultTimeout) == before+1 })
	})

	t.Run("closed by cleanup", func(t *testing.T) {
		before := streamsClosed(t, streamResultClosed)
		h, cli, _ := upgradedStream(t, "foo", func(*Handler) {})
		if err := h.Cleanup(); err != nil {
			t.Fatal(err)
		}
		expectEOF(t, cli)
		waitUntil(t, "stream to be closed", func() bool { return streamsClosed(t, streamResultClosed) == before+1 })
	})
}

