		logs     *StreamLogs
		wantErr  bool
	}{
		{input: `reverse_proxy localhost:80`},
		{input: `reverse_proxy localhost:80 {
			stream_detached
		}`, detached: true},
		{input: `reverse_proxy localhost:80 {
