		}`, logs: &StreamLogs{}},
		{input: `reverse_proxy localhost:80 {
			stream_logs {
				skip_handshake
				level INFO
			}
		}`, logs: &StreamLogs{SkipHandshake: true, Level: "info"}},
		{input: `reverse_proxy localhost:80 {
			stream_detached yes
		}`, wantErr: true},
		{input: `reverse_proxy localhost:80 {
			stream_logs verbose
		}`, wantErr: true},
		{input: `reverse_proxy localhost:80 {
			stream_logs {
				skip_handshake yes
			}
		}`, wantErr: true},
		{input: `reverse_proxy localhost:80 {
			stream_logs {
				level
			}
		}`, wantErr: true},
		{input: `reverse_proxy localhost:80 {
			stream_logs {
				level info debug
			}
		}`, wantErr: true},
		{input: `reverse_proxy localhost:80 {
			stream_logs {
				colour red
			}
		}`, wantErr: true},
	} {
		var h Handler
		err := h.UnmarshalCaddyfile(caddyfile.NewTestDispenser(tc.input))
		if tc.wantErr {
			if err == nil {
				t.Errorf("Test %d: expected an error but got none", i)
			}
			continue
		}
		if err != nil {
			t.Errorf("Test %d: unexpected error: %v", i, err)
			continue
		}
		if h.StreamDetached != tc.detached {
			t.Errorf("Test %d: StreamDetached = %v, want %v", i, h.StreamDetached, tc.detached)
		}
		switch {
		case tc.logs == nil && h.StreamLogs != nil:
			t.Errorf("Test %d: unexpected StreamLogs %+v", i, *h.StreamLogs)
		case tc.logs != nil && (h.StreamLogs == nil || *h.StreamLogs != *tc.logs):
			t.Errorf("Test %d: StreamLogs = %+v, want %+v", i, h.StreamLogs, *tc.logs)
		}
	}
}

