func waitUntil(t *testing.T, what string, cond func() bool) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for !cond() {
		if time.Now().After(deadline) {
			t.Fatalf("timed out waiting for %s", what)
		}
		time.Sleep(5 * time.Millisecond)
	}
}

// settleStreams waits for the streams of earlier tests, which end
// asynchronously, to be fully accounted so metric deltas are exact.
func settleStreams(t *testing.T) {
	t.Helper()
	waitUntil(t, "earlier streams to end", func() bool { return streamsActive(t) == 0 })
}

// TestStreamFinishOnce checks that a stream is accounted exactly once when
// several close paths race to finish it.
func TestStreamFinishOnce(t *testing.T) {
	settleStreams(t)
	durationBefore := streamMetricValue(t, "caddy_reverse_proxy_stream_duration_seconds", nil)
	results := []string{streamResultCompleted, streamResultError, streamResultTimeout, streamResultClosed, streamResultUpstreamRemoved}
	before := make(map[string]float64)
	for _, r := range results {
		before[r] = streamsClosed(t, r)
	}

	st := newStream("upstream")
	if got := streamsActive(t); got != 1 {
		t.Fatalf("active streams = %v, want 1", got)
	}
	var calls int
	var callsMu sync.Mutex
	st.onFinish = func(result string, duration time.Duration, toBackend, fromBackend int64) {
		callsMu.Lock()
		calls++
		callsMu.Unlock()
	}

	var wg sync.WaitGroup
	var firsts int
	var firstsMu sync.Mutex
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if st.finish(results[i%len(results)]) {
				firstsMu.Lock()
				firsts++
				firstsMu.Unlock()
			}
		}()
	}
	wg.Wait()

	if firsts != 1 {
		t.Errorf("%d calls to finish reported being the first, want 1", firsts)
	}
	if calls != 1 {
		t.Errorf("onFinish called %d times, want 1", calls)
	}
	if got := streamsActive(t); got != 0 {
		t.Errorf("active streams = %v after finish, want 0", got)
	}
	if got := streamMetricValue(t, "caddy_reverse_proxy_stream_duration_seconds", nil); got != durationBefore+1 {
		t.Errorf("duration observations = %v, want %v", got, durationBefore+1)
	}
	var total float64
	for _, r := range results {
		total += streamsClosed(t, r) - before[r]
	}
	if total != 1 {
		t.Errorf("streams counted as closed = %v, want 1", total)
	}

	// a nil stream (a connection registered without one) is ignored
	var none *stream
	if none.finish(streamResultClosed) {
		t.Error("finish on a nil stream reported being the first")
	}
}

func TestStreamCountedBytes(t *testing.T) {
	settleStreams(t)
	toBefore, fromBefore := streamBytes(t, streamDirToBackend), streamBytes(t, streamDirFromBackend)

	st := newStream("upstream")
	defer st.finish(streamResultCompleted)

	var toBuf, fromBuf bytes.Buffer
	if _, err := io.WriteString(st.counted(&toBuf, streamDirToBackend), "12345"); err != nil {
		t.Fatal(err)
	}
	if _, err := io.WriteString(st.counted(&fromBuf, streamDirFromBackend), "1234567"); err != nil {
		t.Fatal(err)
	}
	if toBuf.String() != "12345" || fromBuf.String() != "1234567" {
		t.Errorf("data not passed through: %q %q", toBuf.String(), fromBuf.String())
	}
	if st.toBackend.Load() != 5 || st.fromBackend.Load() != 7 {
		t.Errorf("stream counted %d/%d bytes, want 5/7", st.toBackend.Load(), st.fromBackend.Load())
	}
	if got := streamBytes(t, streamDirToBackend) - toBefore; got != 5 {
		t.Errorf("bytes to backend metric moved by %v, want 5", got)
	}
	if got := streamBytes(t, streamDirFromBackend) - fromBefore; got != 7 {
		t.Errorf("bytes from backend metric moved by %v, want 7", got)
	}

	// without a stream the destination is used as is
	var dst bytes.Buffer
	var none *stream
	if w := none.counted(&dst, streamDirToBackend); w != io.Writer(&dst) {
		t.Errorf("nil stream wrapped the writer: %T", w)
	}
}

func TestRegisterStreamMetrics(t *testing.T) {
	// registering twice with the same registry is fine
	core, logs := observer.New(zapcore.DebugLevel)
	reg := prometheus.NewRegistry()
	registerStreamMetrics(reg, zap.New(core))
	registerStreamMetrics(reg, zap.New(core))
	if logs.Len() != 0 {
		t.Errorf("unexpected logs registering twice: %v", logs.All())
	}

	// a clashing collector is logged and does not keep the others from registering
	reg = prometheus.NewRegistry()
	clash := prometheus.NewGauge(prometheus.GaugeOpts{
		Namespace: "caddy", Subsystem: "reverse_proxy", Name: "streams_active", Help: "something else",
	})
	if err := reg.Register(clash); err != nil {
		t.Fatal(err)
	}
	registerStreamMetrics(reg, zap.New(core))
	if logs.Len() != 1 {
		t.Errorf("expected 1 log for the clashing collector, got %v", logs.All())
	}
	mfs, err := reg.Gather()
	if err != nil {
		t.Fatal(err)
	}
	var names []string
	for _, mf := range mfs {
		names = append(names, mf.GetName())
	}
	if !slices.Contains(names, "caddy_reverse_proxy_stream_bytes_total") {
		t.Errorf("remaining collectors not registered: %v", names)
	}
}

func TestDetachedRegistryPrune(t *testing.T) {
	settleStreams(t)
	r := &streamRegistry{streams: make(map[*stream]struct{})}
	var closed []string
	results := make(map[string]string)
	var all []*stream
	add := func(name, upstream string) *stream {
		st := newStream(upstream)
		st.closeFn = func() { closed = append(closed, name) }
		st.onFinish = func(result string, _ time.Duration, _, _ int64) { results[name] = result }
		r.add(st)
		all = append(all, st)
		return st
	}
	add("a", "a:1")
	add("b1", "b:1")
	add("b2", "b:1")
	gone := add("gone", "gone:1")
	r.remove(gone) // a stream that ended on its own is no longer registered

	removedBefore := streamsClosed(t, streamResultUpstreamRemoved)
	n := r.prune(func(upstream string) bool { return upstream == "a:1" })
	if n != 2 {
		t.Errorf("pruned %d streams, want 2", n)
	}
	slices.Sort(closed)
	if !slices.Equal(closed, []string{"b1", "b2"}) {
		t.Errorf("closed streams %v, want [b1 b2]", closed)
	}
	if results["b1"] != streamResultUpstreamRemoved || results["b2"] != streamResultUpstreamRemoved {
		t.Errorf("results %v, want upstream_removed for b1 and b2", results)
	}
	if _, ok := results["a"]; ok {
		t.Error("stream on a retained upstream was closed")
	}
	if got := streamsClosed(t, streamResultUpstreamRemoved) - removedBefore; got != 2 {
		t.Errorf("upstream_removed metric moved by %v, want 2", got)
	}

	// nothing left to prune once everything is retained
	if n := r.prune(func(string) bool { return true }); n != 0 {
		t.Errorf("pruned %d streams, want 0", n)
	}

	for _, st := range all {
		st.finish(streamResultCompleted)
	}
}

func TestUpstreamRetained(t *testing.T) {
	if !upstreamRetained("") {
		t.Error("a stream with an unknown upstream must not be reported as removed")
	}

	const static = "retained-static.test:1"
	if upstreamRetained(static) {
		t.Fatal("unknown upstream reported as retained")
	}
	hosts.LoadOrStore(static, new(Host))
	if !upstreamRetained(static) {
		t.Error("upstream in the pool reported as removed")
	}
	_, _ = hosts.Delete(static)
	if upstreamRetained(static) {
		t.Error("upstream deleted from the pool reported as retained")
	}

	const dynamic = "retained-dynamic.test:1"
	dynamicHostsMu.Lock()
	dynamicHosts[dynamic] = dynamicHostEntry{host: new(Host), lastSeen: time.Now()}
	dynamicHostsMu.Unlock()
	defer func() {
		dynamicHostsMu.Lock()
		delete(dynamicHosts, dynamic)
		dynamicHostsMu.Unlock()
	}()
	if !upstreamRetained(dynamic) {
		t.Error("dynamic upstream reported as removed")
	}
}

