		}`, wantErr: true},
		{input: `reverse_proxy localhost:80 {
			stream_logs verbose
		}`, wantErr: true},
		{input: `reverse_proxy localhost:80 {
			stream_logs {
				skip_handshake yes
			}
		}`, wantErr: true},
