// upgradedStream runs an upgrade through a handler against a real backend
// and returns the handler and both ends of the established stream.
func upgradedStream(t *testing.T, upgrade string, configure func(h *Handler)) (h *Handler, cli, srv *net.TCPConn) {
	t.Helper()

	srvc := make(chan *net.TCPConn, 1)
	backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		conn, _, err := http.NewResponseController(w).Hijack()
		if err != nil {
			t.Errorf("backend hijack failed: %v", err)
			return
		}
		tcp := conn.(*net.TCPConn)
		if _, err := io.WriteString(tcp, "HTTP/1.1 101 Switching Protocols\r\nConnection: Upgrade\r\nUpgrade: "+upgrade+"\r\n\r\n"); err != nil {
			tcp.Close()
			t.Errorf("backend upgrade write failed: %v", err)
			return
		}
		srvc <- tcp
	}))
	t.Cleanup(backend.Close)

	h = minimalHandler(0, &Upstream{Host: new(Host), Dial: backend.Listener.Addr().String()})
	h.connections = make(map[io.ReadWriteCloser]openConnection)
	h.connectionsMu = new(sync.Mutex)
	configure(h)

	frontend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r = r.WithContext(context.WithoutCancel(r.Context()))
		_ = h.ServeHTTP(w, prepareTestRequest(r), caddyhttp.HandlerFunc(func(http.ResponseWriter, *http.Request) error {
			return nil
		}))
	}))
	t.Cleanup(frontend.Close)

	frontendURL, err := url.Parse(frontend.URL)
	if err != nil {
		t.Fatal(err)
	}
	addr, err := net.ResolveTCPAddr("tcp", frontendURL.Host)
	if err != nil {
		t.Fatal(err)
	}
	cli, err = net.DialTCP("tcp", nil, addr)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { cli.Close() })

	req, _ := http.NewRequest(http.MethodGet, frontend.URL, nil)
	req.Header.Set("Connection", "Upgrade")
	req.Header.Set("Upgrade", upgrade)
	if err := req.Write(cli); err != nil {
		t.Fatal(err)
	}
	resp, err := http.ReadResponse(bufio.NewReader(cli), &http.Request{Method: http.MethodGet})
	if err != nil {
		t.Fatalf("failed to read upgrade response: %v", err)
	}
	if resp.StatusCode != http.StatusSwitchingProtocols {
		t.Fatalf("status = %d, want 101", resp.StatusCode)
	}

	select {
	case srv = <-srvc:
	case <-time.After(5 * time.Second):
		t.Fatal("timed out waiting for the backend connection")
	}
	t.Cleanup(func() { srv.Close() })
	return h, cli, srv
}

func expectRead(t *testing.T, conn *net.TCPConn, msg string) {
	t.Helper()
	_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	b := make([]byte, len(msg))
	if _, err := io.ReadFull(conn, b); err != nil {
		t.Fatalf("failed to read %q: %v", msg, err)
	}
	if string(b) != msg {
		t.Fatalf("got %q, want %q", b, msg)
	}
}

// expectClosed reads the connection until the peer closes it and returns
// what was received before that.
func expectClosed(t *testing.T, conn *net.TCPConn) []byte {
	t.Helper()
	_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	b, _ := io.ReadAll(conn) // a reset instead of an EOF is a close too
	if ne, ok := conn.SetReadDeadline(time.Time{}), error(nil); ok != ne && ne == nil {
		t.Fatal("unreachable")
	}
	return b
}

func TestUpgradedStreamResults(t *testing.T) {
	switch runtime.GOOS {
	case "plan9", "js", "wasip1":
		t.Skipf("not supported on %s", runtime.GOOS)
	}

	t.Run("completed with bytes", func(t *testing.T) {
		settleStreams(t)
		completedBefore := streamsClosed(t, streamResultCompleted)
		toBefore, fromBefore := streamBytes(t, streamDirToBackend), streamBytes(t, streamDirFromBackend)

		_, cli, srv := upgradedStream(t, "foo", func(*Handler) {})
		if got := streamsActive(t); got != 1 {
			t.Errorf("active streams = %v, want 1", got)
		}
		if _, err := cli.Write([]byte("hello")); err != nil {
			t.Fatal(err)
		}
		expectRead(t, srv, "hello")
		if _, err := srv.Write([]byte("world!!")); err != nil {
			t.Fatal(err)
		}
		expectRead(t, cli, "world!!")
		_ = cli.CloseWrite()
		_ = srv.CloseWrite()

		waitUntil(t, "stream to complete", func() bool { return streamsActive(t) == 0 })
		if got := streamsClosed(t, streamResultCompleted) - completedBefore; got != 1 {
			t.Errorf("completed streams moved by %v, want 1", got)
		}
		if got := streamBytes(t, streamDirToBackend) - toBefore; got != 5 {
			t.Errorf("bytes to backend moved by %v, want 5", got)
		}
		if got := streamBytes(t, streamDirFromBackend) - fromBefore; got != 7 {
			t.Errorf("bytes from backend moved by %v, want 7", got)
		}
	})

	t.Run("timeout", func(t *testing.T) {
		settleStreams(t)
		before := streamsClosed(t, streamResultTimeout)
		_, cli, _ := upgradedStream(t, "foo", func(h *Handler) { h.StreamTimeout = caddy.Duration(50 * time.Millisecond) })
		expectClosed(t, cli)
		waitUntil(t, "stream to time out", func() bool { return streamsClosed(t, streamResultTimeout) == before+1 })
	})

	t.Run("closed by cleanup", func(t *testing.T) {
		settleStreams(t)
		before := streamsClosed(t, streamResultClosed)
		h, cli, _ := upgradedStream(t, "foo", func(*Handler) {})
		if err := h.Cleanup(); err != nil {
			t.Fatal(err)
		}
		expectClosed(t, cli)
		waitUntil(t, "stream to be closed", func() bool { return streamsClosed(t, streamResultClosed) == before+1 })
	})
}

func TestDetachedStreamCleanup(t *testing.T) {
	switch runtime.GOOS {
	case "plan9", "js", "wasip1":
		t.Skipf("not supported on %s", runtime.GOOS)
	}

	detached := func(h *Handler) { h.StreamDetached = true }

	t.Run("survives while upstream is retained", func(t *testing.T) {
		settleStreams(t)
		removedBefore := streamsClosed(t, streamResultUpstreamRemoved)
		h, cli, srv := upgradedStream(t, "foo", detached)
		dial := h.Upstreams[0].Dial

		// the upstream is in the pool twice: the old config and the new one
		hosts.LoadOrStore(dial, new(Host))
		hosts.LoadOrStore(dial, new(Host))
		if err := h.Cleanup(); err != nil {
			t.Fatal(err)
		}

		if _, err := cli.Write([]byte("still here")); err != nil {
			t.Fatal(err)
		}
		expectRead(t, srv, "still here")
		h.connectionsMu.Lock()
		registered := len(h.connections)
		h.connectionsMu.Unlock()
		if registered != 0 {
			t.Error("detached stream was registered with the handler")
		}

		// the new config drops the upstream
		_, _ = hosts.Delete(dial)
		detachedStreams.prune(upstreamRetained)
		expectClosed(t, cli)
		waitUntil(t, "stream to be closed", func() bool {
			return streamsClosed(t, streamResultUpstreamRemoved) == removedBefore+1
		})
	})

	for _, upgrade := range []string{"foo", "websocket"} {
		t.Run("closed when upstream removed/"+upgrade, func(t *testing.T) {
			settleStreams(t)
			removedBefore := streamsClosed(t, streamResultUpstreamRemoved)
			h, cli, _ := upgradedStream(t, upgrade, detached)
			hosts.LoadOrStore(h.Upstreams[0].Dial, new(Host))

			if err := h.Cleanup(); err != nil {
				t.Fatal(err)
			}

			got := expectClosed(t, cli)
			if upgrade == "websocket" {
				if !bytes.HasPrefix(got, []byte{0x88, 0x02, 0x03, 0xe9}) {
					t.Errorf("client did not get a close frame: %x", got)
				}
			} else if len(got) != 0 {
				t.Errorf("unexpected data before close: %x", got)
			}
			waitUntil(t, "stream to be closed", func() bool {
				return streamsClosed(t, streamResultUpstreamRemoved) == removedBefore+1
			})
		})
	}
}

// A response carrying the Incremental header field (RFC 10036) must be
// forwarded without buffering,

toolUseResult.newString:
// streamMetricValue returns the current value of a stream metric: the
// value of a counter or gauge, or the sample count of a histogram. The
// collectors are shared by the whole process, so tests compare deltas.
func streamMetricValue(t *testing.T, name string, labels map[string]string) float64 {
	t.Helper()
	reg := prometheus.NewRegistry()
	registerStreamMetrics(reg, zap.NewNop())
	mfs, err := reg.Gather()
	if err != nil {
		t.Fatalf("gathering metrics: %v", err)
	}
	for _, mf := range mfs {
		if mf.GetName() != name {
			continue
		}
	metrics:
		for _, m := range mf.GetMetric() {
			for k, v := range labels {
				found := false
				for _, lp := range m.GetLabel() {
					if lp.GetName() == k && lp.GetValue() == v {
						found = true
					}
				}
				if !found {
					continue metrics
				}
			}
			switch {
			case m.GetHistogram() != nil:
				return float64(m.GetHistogram().GetSampleCount())
			case m.GetGauge() != nil:
				return m.GetGauge().GetValue()
			default:
				return m.GetCounter().GetValue()
			}
		}
	}
	return 0
}

func streamsClosed(t *testing.T, result string) float64 {
	t.Helper()
	return streamMetricValue(t, "caddy_reverse_proxy_streams_closed_total", map[string]string{"result": result})
}

func streamsActive(t *testing.T) float64 {
	t.Helper()
	return streamMetricValue(t, "caddy_reverse_proxy_streams_active", nil)
}

func streamBytes(t *testing.T, direction string) float64 {
	t.Helper()
	return streamMetricValue(t, "caddy_reverse_proxy_stream_bytes_total", map[string]string{"direction": direction})
}

func waitUntil(t *testing.T, what string, cond func() bool) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for !cond() {
		if time.Now().After(deadline) {
			t.Fatalf("timed out waiting for %s", what)
		}
		time.Sleep(5 * time.Millisecond)
	}
}

// settleStreams waits for the streams of earlier tests, which end
// asynchronously, to be fully accounted so metric deltas are exact.
func settleStreams(t *testing.T) {
	t.Helper()
	waitUntil(t, "earlier streams to end", func() bool { return streamsActive(t) == 0 })
}

// TestStreamFinishOnce checks that a stream is accounted exactly once when
// several close paths race to finish it.
func TestStreamFinishOnce(t *testing.T) {
	settleStreams(t)
	durationBefore := streamMetricValue(t, "caddy_reverse_proxy_stream_duration_seconds", nil)
	results := []string{streamResultCompleted, streamResultError, streamResultTimeout, streamResultClosed, streamResultUpstreamRemoved}
	before := make(map[string]float64)
	for _, r := range results {
		before[r] = streamsClosed(t, r)
	}

	st := newStream("upstream")
	if got := streamsActive(t); got != 1 {
		t.Fatalf("active streams = %v, want 1", got)
	}
	var calls int
	var callsMu sync.Mutex
	st.onFinish = func(result string, duration time.Duration, toBackend, fromBackend int64) {
		callsMu.Lock()
		calls++
		callsMu.Unlock()
	}

	var wg sync.WaitGroup
	var firsts int
	var firstsMu sync.Mutex
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if st.finish(results[i%len(results)]) {
				firstsMu.Lock()
				firsts++
				firstsMu.Unlock()
			}
		}()
	}
	wg.Wait()

	if firsts != 1 {
		t.Errorf("%d calls to finish reported being the first, want 1", firsts)
	}
	if calls != 1 {
		t.Errorf("onFinish called %d times, want 1", calls)
	}
	if got := streamsActive(t); got != 0 {
		t.Errorf("active streams = %v after finish, want 0", got)
	}
	if got := streamMetricValue(t, "caddy_reverse_proxy_stream_duration_seconds", nil); got != durationBefore+1 {
		t.Errorf("duration observations = %v, want %v", got, durationBefore+1)
	}
	var total float64
	for _, r := range results {
		total += streamsClosed(t, r) - before[r]
	}
	if total != 1 {
		t.Errorf("streams counted as closed = %v, want 1", total)
	}

	// a nil stream (a connection registered without one) is ignored
	var none *stream
	if none.finish(streamResultClosed) {
		t.Error("finish on a nil stream reported being the first")
	}
}

func TestStreamCountedBytes(t *testing.T) {
	settleStreams(t)
	toBefore, fromBefore := streamBytes(t, streamDirToBackend), streamBytes(t, streamDirFromBackend)

	st := newStream("upstream")
	defer st.finish(streamResultCompleted)

	var toBuf, fromBuf bytes.Buffer
	if _, err := io.WriteString(st.counted(&toBuf, streamDirToBackend), "12345"); err != nil {
		t.Fatal(err)
	}
	if _, err := io.WriteString(st.counted(&fromBuf, streamDirFromBackend), "1234567"); err != nil {
		t.Fatal(err)
	}
	if toBuf.String() != "12345" || fromBuf.String() != "1234567" {
		t.Errorf("data not passed through: %q %q", toBuf.String(), fromBuf.String())
	}
	if st.toBackend.Load() != 5 || st.fromBackend.Load() != 7 {
		t.Errorf("stream counted %d/%d bytes, want 5/7", st.toBackend.Load(), st.fromBackend.Load())
	}
	if got := streamBytes(t, streamDirToBackend) - toBefore; got != 5 {
		t.Errorf("bytes to backend metric moved by %v, want 5", got)
	}
	if got := streamBytes(t, streamDirFromBackend) - fromBefore; got != 7 {
		t.Errorf("bytes from backend metric moved by %v, want 7", got)
	}

	// without a stream the destination is used as is
	var dst bytes.Buffer
	var none *stream
	if w := none.counted(&dst, streamDirToBackend); w != io.Writer(&dst) {
		t.Errorf("nil stream wrapped the writer: %T", w)
	}
}

func TestRegisterStreamMetrics(t *testing.T) {
	// registering twice with the same registry is fine
	core, logs := observer.New(zapcore.DebugLevel)
	reg := prometheus.NewRegistry()
	registerStreamMetrics(reg, zap.New(core))
	registerStreamMetrics(reg, zap.New(core))
	if logs.Len() != 0 {
		t.Errorf("unexpected logs registering twice: %v", logs.All())
	}

	// a clashing collector is logged and does not keep the others from registering
	reg = prometheus.NewRegistry()
	clash := prometheus.NewGauge(prometheus.GaugeOpts{
		Namespace: "caddy", Subsystem: "reverse_proxy", Name: "streams_active", Help: "something else",
	})
	if err := reg.Register(clash); err != nil {
		t.Fatal(err)
	}
	registerStreamMetrics(reg, zap.New(core))
	if logs.Len() != 1 {
		t.Errorf("expected 1 log for the clashing collector, got %v", logs.All())
	}
	mfs, err := reg.Gather()
	if err != nil {
		t.Fatal(err)
	}
	var names []string
	for _, mf := range mfs {
		names = append(names, mf.GetName())
	}
	if !slices.Contains(names, "caddy_reverse_proxy_stream_bytes_total") {
		t.Errorf("remaining collectors not registered: %v", names)
	}
}

func TestDetachedRegistryPrune(t *testing.T) {
	settleStreams(t)
	r := &streamRegistry{streams: make(map[*stream]struct{})}
	var closed []string
	results := make(map[string]string)
	var all []*stream
	add := func(name, upstream string) *stream {
		st := newStream(upstream)
		st.closeFn = func() { closed = append(closed, name) }
		st.onFinish = func(result string, _ time.Duration, _, _ int64) { results[name] = result }
		r.add(st)
		all = append(all, st)
		return st
	}
	add("a", "a:1")
	add("b1", "b:1")
	add("b2", "b:1")
	gone := add("gone", "gone:1")
	r.remove(gone) // a stream that ended on its own is no longer registered

	removedBefore := streamsClosed(t, streamResultUpstreamRemoved)
	n := r.prune(func(upstream string) bool { return upstream == "a:1" })
	if n != 2 {
		t.Errorf("pruned %d streams, want 2", n)
	}
	slices.Sort(closed)
	if !slices.Equal(closed, []string{"b1", "b2"}) {
		t.Errorf("closed streams %v, want [b1 b2]", closed)
	}
	if results["b1"] != streamResultUpstreamRemoved || results["b2"] != streamResultUpstreamRemoved {
		t.Errorf("results %v, want upstream_removed for b1 and b2", results)
	}
	if _, ok := results["a"]; ok {
		t.Error("stream on a retained upstream was closed")
	}
	if got := streamsClosed(t, streamResultUpstreamRemoved) - removedBefore; got != 2 {
		t.Errorf("upstream_removed metric moved by %v, want 2", got)
	}

	// nothing left to prune once everything is retained
	if n := r.prune(func(string) bool { return true }); n != 0 {
		t.Errorf("pruned %d streams, want 0", n)
	}

	for _, st := range all {
		st.finish(streamResultCompleted)
	}
}

func TestUpstreamRetained(t *testing.T) {
	if !upstreamRetained("") {
		t.Error("a stream with an unknown upstream must not be reported as removed")
	}

	const static = "retained-static.test:1"
	if upstreamRetained(static) {
		t.Fatal("unknown upstream reported as retained")
	}
	hosts.LoadOrStore(static, new(Host))
	if !upstreamRetained(static) {
		t.Error("upstream in the pool reported as removed")
	}
	_, _ = hosts.Delete(static)
	if upstreamRetained(static) {
		t.Error("upstream deleted from the pool reported as retained")
	}

	const dynamic = "retained-dynamic.test:1"
	dynamicHostsMu.Lock()
	dynamicHosts[dynamic] = dynamicHostEntry{host: new(Host), lastSeen: time.Now()}
	dynamicHostsMu.Unlock()
	defer func() {
