package caddyhttp

import (
	"bytes"
	"io"
	"net/http"
	"strings"
	"testing"
)

type responseWriterSpy interface {
	http.ResponseWriter
	Written() string
	CalledReadFrom() bool
}

var (
	_ responseWriterSpy = (*baseRespWriter)(nil)
	_ responseWriterSpy = (*readFromRespWriter)(nil)
)

// a barebones http.ResponseWriter mock
type baseRespWriter []byte

func (brw *baseRespWriter) Write(d []byte) (int, error) {
	*brw = append(*brw, d...)
	return len(d), nil
}
func (brw *baseRespWriter) Header() http.Header        { return nil }
func (brw *baseRespWriter) WriteHeader(statusCode int) {}
func (brw *baseRespWriter) Written() string            { return string(*brw) }
func (brw *baseRespWriter) CalledReadFrom() bool       { return false }

// an http.ResponseWriter mock that supports ReadFrom
type readFromRespWriter struct {
	baseRespWriter
	called bool
}

func (rf *readFromRespWriter) ReadFrom(r io.Reader) (int64, error) {
	rf.called = true
	return io.Copy(&rf.baseRespWriter, r)
}

func (rf *readFromRespWriter) CalledReadFrom() bool { return rf.called }

func TestResponseWriterWrapperReadFrom(t *testing.T) {
	tests := map[string]struct {
		responseWriter responseWriterSpy
		wantReadFrom   bool
	}{
		"no ReadFrom": {
			responseWriter: &baseRespWriter{},
			wantReadFrom:   false,
		},
		"has ReadFrom": {
			responseWriter: &readFromRespWriter{},
			wantReadFrom:   true,
		},
	}
	for name, tt := range tests {
		t.Run(name, func(t *testing.T) {
			// what we expect middlewares to do:
			type myWrapper struct {
				*ResponseWriterWrapper
			}

			wrapped := myWrapper{
				ResponseWriterWrapper: &ResponseWriterWrapper{ResponseWriter: tt.responseWriter},
			}

			const srcData = "boo!"
			// hides everything but Read, since strings.Reader implements WriteTo it would
			// take precedence over our ReadFrom.
			src := struct{ io.Reader }{strings.NewReader(srcData)}

			if _, err := io.Copy(wrapped, src); err != nil {
				t.Errorf("%s: Copy() err = %v", name, err)
			}

			if got := tt.responseWriter.Written(); got != srcData {
				t.Errorf("%s: data = %q, want %q", name, got, srcData)
			}

			if tt.responseWriter.CalledReadFrom() != tt.wantReadFrom {
				if tt.wantReadFrom {
					t.Errorf("%s: ReadFrom() should have been called", name)
				} else {
					t.Errorf("%s: ReadFrom() should not have been called", name)
				}
			}
		})
	}
}

func TestResponseWriterWrapperUnwrap(t *testing.T) {
	w := &ResponseWriterWrapper{&baseRespWriter{}}

	if _, ok := w.Unwrap().(*baseRespWriter); !ok {
		t.Errorf("Unwrap() doesn't return the underlying ResponseWriter")
	}
}

// an http.ResponseWriter mock that records what is written to it and can be hijacked
type hijackableRespWriter struct {
	header    http.Header
	statuses  []int
	body      bytes.Buffer
	conn      net.Conn
	hijackErr error
}

func (w *hijackableRespWriter) Header() http.Header {
	if w.header == nil {
		w.header = make(http.Header)
	}
	return w.header
}
func (w *hijackableRespWriter) WriteHeader(statusCode int) { w.statuses = append(w.statuses, statusCode) }
func (w *hijackableRespWriter) Write(d []byte) (int, error) {
	return w.body.Write(d)
}

func (w *hijackableRespWriter) Hijack() (net.Conn, *bufio.ReadWriter, error) {
	if w.hijackErr != nil {
		return nil, nil, w.hijackErr
	}
	return w.conn, bufio.NewReadWriter(bufio.NewReader(w.conn), bufio.NewWriter(w.conn)), nil
}

func TestResponseRecorderNoWriteAfterHijack(t *testing.T) {
	for name, shouldBuffer := range map[string]ShouldBufferFunc{
		"streamed": nil,
		"buffered": func(int, http.Header) bool { return true },
	} {
		t.Run(name, func(t *testing.T) {
			server, client := net.Pipe()
			defer server.Close()
			defer client.Close()
			w := &hijackableRespWriter{conn: server}
			rr := NewResponseRecorder(w, new(bytes.Buffer), shouldBuffer)

			conn, _, err := http.NewResponseController(rr).Hijack()
			if err != nil {
				t.Fatalf("Hijack() err = %v", err)
			}
			if UnwrapHijackedConn(conn) != net.Conn(server) {
				t.Error("UnwrapHijackedConn() did not return the raw connection")
			}

			rr.WriteHeader(http.StatusOK)
			if n, err := rr.Write([]byte("late")); n != 0 || !errors.Is(err, http.ErrHijacked) {
				t.Errorf("Write() = %d, %v; want 0, ErrHijacked", n, err)
			}
			if n, err := rr.(io.ReaderFrom).ReadFrom(strings.NewReader("late")); n != 0 || !errors.Is(err, http.ErrHijacked) {
				t.Errorf("ReadFrom() = %d, %v; want 0, ErrHijacked", n, err)
			}
			if err := rr.WriteResponse(); err != nil {
				t.Errorf("WriteResponse() err = %v", err)
			}
			if err := http.NewResponseController(rr).Flush(); !errors.Is(err, http.ErrHijacked) {
				t.Errorf("Flush() err = %v, want ErrHijacked", err)
			}

			if len(w.statuses) != 0 || w.body.Len() != 0 || rr.Buffer().Len() != 0 {
				t.Errorf("something was written after the hijack: statuses %v, body %q, buffer %q",
					w.statuses, w.body.String(), rr.Buffer().String())
			}
			if rr.Status() != 0 {
				t.Errorf("Status() = %d, want 0", rr.Status())
			}
		})
	}

	// a failed hijack leaves the recorder usable
	w := &hijackableRespWriter{hijackErr: http.ErrNotSupported}
	rr := NewResponseRecorder(w, nil, nil)
	if _, _, err := http.NewResponseController(rr).Hijack(); !errors.Is(err, http.ErrNotSupported) {
		t.Fatalf("Hijack() err = %v, want ErrNotSupported", err)
	}
	if _, err := rr.Write([]byte("ok")); err != nil || w.body.String() != "ok" {
		t.Errorf("Write() after a failed hijack: err = %v, body %q", err, w.body.String())
	}

	// connections that are not wrapped by a recorder are returned as is
	server, client := net.Pipe()
	defer server.Close()
	defer client.Close()
	if UnwrapHijackedConn(server) != net.Conn(server) {
		t.Error("UnwrapHijackedConn() changed a connection that is not wrapped")
	}
}

