// A 101 Switching Protocols response is final: once it is written, nothing
// else reaches the underlying writer, neither from the handler nor when the
// encode writer is closed.
func TestEncodeUpgradeFinal101(t *testing.T) {
	enc := newTestEncode(t)

	t.Run("writer", func(t *testing.T) {
		w := &spyWriter{}
		rw := enc.openResponseWriter("gzip", w, false)

		rw.WriteHeader(http.StatusSwitchingProtocols)
		rw.WriteHeader(http.StatusOK)
		if n, err := rw.Write([]byte("late")); n != 0 || !errors.Is(err, http.ErrHijacked) {
			t.Errorf("Write() = %d, %v; want 0, ErrHijacked", n, err)
		}
		if n, err := rw.ReadFrom(strings.NewReader("late")); n != 0 || !errors.Is(err, http.ErrHijacked) {
			t.Errorf("ReadFrom() = %d, %v; want 0, ErrHijacked", n, err)
		}
		if err := rw.Close(); err != nil {
			t.Errorf("Close() err = %v", err)
		}

		if !slices.Equal(w.statuses, []int{http.StatusSwitchingProtocols}) || w.body.Len() != 0 {
			t.Errorf("written: statuses %v, body %q; want only 101", w.statuses, w.body.String())
		}
		if w.Header().Get("Content-Encoding") != "" {
			t.Error("a 101 response was encoded")
		}
	})

	t.Run("through ServeHTTP", func(t *testing.T) {
		server, client := net.Pipe()
		defer server.Close()
		defer client.Close()
		w := hijackSpyWriter{&spyWriter{}, server}

		r := httptest.NewRequest(http.MethodGet, "/ws", nil)
		r.Header.Set("Accept-Encoding", "gzip")
		r.Header.Set("Connection", "Upgrade")
		r.Header.Set("Upgrade", "websocket")

		err := enc.ServeHTTP(w, r, caddyhttp.HandlerFunc(func(w http.ResponseWriter, r *http.Request) error {
			w.Header().Set("Upgrade", "websocket")
			w.WriteHeader(http.StatusSwitchingProtocols)
			conn, _, err := http.NewResponseController(w).Hijack()
			if err != nil {
				return err
			}
			if conn != net.Conn(server) {
				t.Errorf("hijacked conn %T is not the underlying connection", conn)
			}
			return nil
