// h2Client is a minimal HTTP/2 client speaking raw frames, since the
// standard clients do not send extended CONNECT requests.
type h2Client struct {
	conn net.Conn
	fr   *http2.Framer
	dec  *hpack.Decoder
}

func dialH2(t *testing.T) *h2Client {
	t.Helper()
	conn, err := tls.DialWithDialer(&net.Dialer{Timeout: 5 * time.Second}, "tcp", "127.0.0.1:9443", &tls.Config{
		InsecureSkipVerify: true, //nolint:gosec
		ServerName:         "localhost",
		NextProtos:         []string{"h2"},
	})
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	t.Cleanup(func() { conn.Close() })
	if conn.ConnectionState().NegotiatedProtocol != "h2" {
		t.Fatalf("negotiated %q, want h2", conn.ConnectionState().NegotiatedProtocol)
	}
	_ = conn.SetDeadline(time.Now().Add(15 * time.Second))

	c := &h2Client{conn: conn, fr: http2.NewFramer(conn, conn), dec: hpack.NewDecoder(4096, nil)}
	if _, err := io.WriteString(conn, http2.ClientPreface); err != nil {
		t.Fatal(err)
	}
	if err := c.fr.WriteSettings(); err != nil {
		t.Fatal(err)
	}
	return c
}

// next returns the next frame, answering the connection-level frames
// (settings, pings) that are not interesting to the test.
func (c *h2Client) next(t *testing.T) http2.Frame {
	t.Helper()
	for {
		f, err := c.fr.ReadFrame()
		if err != nil {
			t.Fatalf("reading frame: %v", err)
		}
		switch f := f.(type) {
		case *http2.SettingsFrame:
			if f.IsAck() {
				continue
			}
			if v, ok := f.Value(http2.SettingID(8)); !ok || v != 1 {
				t.Fatalf("server did not advertise SETTINGS_ENABLE_CONNECT_PROTOCOL (extended CONNECT)")
			}
			if err := c.fr.WriteSettingsAck(); err != nil {
				t.Fatal(err)
			}
		case *http2.PingFrame:
			if !f.IsAck() {
				_ = c.fr.WritePing(true, f.Data)
			}
		case *http2.WindowUpdateFrame:
		default:
			return f
		}
	}
}

func TestExtendedConnectH2(t *testing.T) {
	// the HTTP/2 server only offers extended CONNECT (RFC 8441) with this setting
	t.Setenv("GODEBUG", "http2xconnect=1")

	for _, tc := range []struct{ name, opts string }{
		{name: "default"},
		{name: "detached", opts: "stream_detached"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			startWSBackend(t, 9101)
			tester := caddytest.NewTester(t)
			tester.InitServer(fmt.Sprintf(`%s

localhost:9443 {
	reverse_proxy 127.0.0.1:9101 {
		%s
	}
}
`, streamGlobalOptions, tc.opts), "caddyfile")

			c := dialH2(t)
			var hb bytes.Buffer
			enc := hpack.NewEncoder(&hb)
			for _, hf := range []hpack.HeaderField{
				{Name: ":method", Value: "CONNECT"},
				{Name: ":scheme", Value: "https"},
				{Name: ":path", Value: "/ws"},
				{Name: ":authority", Value: "localhost:9443"},
				{Name: ":protocol", Value: "websocket"},
				{Name: "sec-websocket-version", Value: "13"},
			} {
				if err := enc.WriteField(hf); err != nil {
					t.Fatal(err)
				}
			}
			if err := c.fr.WriteHeaders(http2.HeadersFrameParam{StreamID: 1, BlockFragment: hb.Bytes(), EndHeaders: true}); err != nil {
				t.Fatal(err)
			}

			// the response to the extended CONNECT is a 200
			hf, ok := c.next(t).(*http2.HeadersFrame)
			if !ok {
				t.Fatal("expected a HEADERS frame as the response")
			}
			fields, err := c.dec.DecodeFull(hf.HeaderBlockFragment())
			if err != nil {
				t.Fatal(err)
			}
			status := ""
			for _, f := range fields {
				if f.Name == ":status" {
					status = f.Value
				}
			}
			if status != "200" {
				t.Fatalf("extended CONNECT status = %q, want 200", status)
			}

			// bytes flow both ways through the tunnel
			for _, msg := range []string{"over h2", "and again"} {
				if err := c.fr.WriteData(1, false, []byte(msg)); err != nil {
					t.Fatal(err)
				}
				var got []byte
				for len(got) < len(msg) {
					df, ok := c.next(t).(*http2.DataFrame)
					if !ok {
						t.Fatal("expected a DATA frame")
					}
					got = append(got, df.Data()...)
				}
				if string(got) != msg {
					t.Fatalf("echo = %q, want %q", got, msg)
				}
			}
		})
	}
}

