// readLogEntries returns the JSON log entries written to path so far.
func readLogEntries(t *testing.T, path string) []map[string]any {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		t.Fatalf("reading log: %v", err)
	}
	var entries []map[string]any
	for _, line := range bytes.Split(data, []byte("\n")) {
		if len(bytes.TrimSpace(line)) == 0 {
			continue
		}
		var e map[string]any
		if err := json.Unmarshal(line, &e); err != nil {
			continue // not a JSON entry (partially written)
		}
		entries = append(entries, e)
	}
	return entries
}

func findLogEntry(entries []map[string]any, match func(e map[string]any) bool) map[string]any {
	for _, e := range entries {
		if match(e) {
			return e
		}
	}
	return nil
}

func isStreamClosedEntry(e map[string]any) bool { return e["msg"] == "stream closed" }

func isHandshakeEntry(e map[string]any) bool {
	req, _ := e["request"].(map[string]any)
	return e["msg"] == "handled request" && req != nil && req["uri"] == "/ws"
}

func waitForLogEntry(t *testing.T, path string, match func(e map[string]any) bool) map[string]any {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		if e := findLogEntry(readLogEntries(t, path), match); e != nil {
			return e
		}
		time.Sleep(50 * time.Millisecond)
	}
	t.Fatalf("expected log entry not found; log has %v", readLogEntries(t, path))
	return nil
}

func TestDetachedStreamAccessLog(t *testing.T) {
	for _, tc := range []struct {
		name          string
		skipHandshake bool
	}{
		{name: "handshake logged", skipHandshake: false},
		{name: "handshake skipped", skipHandshake: true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			startWSBackend(t, 9101)
			tester := caddytest.NewTester(t)
			logPath := filepath.ToSlash(filepath.Join(t.TempDir(), "access.log"))

			skip := ""
			if tc.skipHandshake {
				skip = "skip_handshake"
			}
			site := func(gen int) string {
				return streamSite(gen, fmt.Sprintf(`	log access {
		output file %s
		format json
		level INFO
	}
	reverse_proxy 127.0.0.1:9101 {
		stream_detached
		stream_logs {
			%s
			level info
		}
	}`, logPath, skip))
			}

			tester.InitServer(site(1), "caddyfile")
			c, _ := dialWS(t, "/ws", nil)
			c.echo(t, "hello")
			c.echo(t, "again!!")

			// reload while the stream is open: it outlives the config it started with
			tester.InitServer(site(2), "caddyfile")
			c.echo(t, "after reload")
			c.Close()

			closed := waitForLogEntry(t, logPath, isStreamClosedEntry)
			if logger, _ := closed["logger"].(string); !strings.HasPrefix(logger, "http.log.access") {
				t.Errorf("stream close logged by %q, want an access logger", logger)
			}
			if closed["level"] != "info" {
				t.Errorf("stream close logged at %v, want info", closed["level"])
			}
			if closed["upstream"] != "127.0.0.1:9101" {
				t.Errorf("upstream = %v, want 127.0.0.1:9101", closed["upstream"])
			}
			const total = len("hello") + len("again!!") + len("after reload")
			if closed["bytes_to_backend"] != float64(total) || closed["bytes_from_backend"] != float64(total) {
				t.Errorf("bytes = %v to / %v from backend, want %d each",
					closed["bytes_to_backend"], closed["bytes_from_backend"], total)
			}

			if tc.skipHandshake {
				// the handshake entry is written after the stream close one
				time.Sleep(time.Second)
				if e := findLogEntry(readLogEntries(t, logPath), isHandshakeEntry); e != nil {
					t.Errorf("handshake was logged despite skip_handshake: %v", e)
				}
			} else {
				waitForLogEntry(t, logPath, isHandshakeEntry)
			}
		})
	}
}

