// The HTTP/2 server only offers extended CONNECT (RFC 8441) when the process
// is started with this GODEBUG setting, so the test runs in a child process
// that has it. The child uses its own admin and listening ports, since the
// Caddy of this process may still hold the usual ones.
const h2xconnectSetting = "http2xconnect=1"

func TestExtendedConnectH2(t *testing.T) {
	if !strings.Contains(os.Getenv("GODEBUG"), h2xconnectSetting) {
		if testing.Short() {
			t.Skip("integration test")
		}
		cmd := exec.Command(os.Args[0], "-test.run=^TestExtendedConnectH2$", "-test.count=1", "-test.v")
		cmd.Env = append(os.Environ(), "GODEBUG="+h2xconnectSetting)
		out, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("extended CONNECT test failed in the child process: %v\n%s", err, out)
		}
		return
	}

	const (
		adminPort = 2998
		httpPort  = 9081
		httpsPort = 9444
	)
	for _, tc := range []struct{ name, opts string }{
		{name: "default"},
		{name: "detached", opts: "stream_detached"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			startWSBackend(t, 9101)
			tester := caddytest.NewTester(t).WithDefaultOverrides(caddytest.Config{AdminPort: adminPort})
			tester.InitServer(fmt.Sprintf(`{
	skip_install_trust
	admin localhost:%d
	http_port     %d
	https_port    %d
	grace_period  1ns
}

localhost:%d {
	reverse_proxy 127.0.0.1:9101 {
		%s
	}
}
`, adminPort, httpPort, httpsPort, httpsPort, tc.opts), "caddyfile")

			c := dialH2(t, httpsPort)

