var debugOnly = "TestZZZIntercept" // TEMPDEBUG

func TestZZZIntercept(t *testing.T) { // TEMPDEBUG
	startWSBackend(t, 9101)
	tester := caddytest.NewTester(t)
	tester.InitServer(streamSite(1, `	intercept {
		handle_response {
			respond "intercepted" 500
		}
	}
	reverse_proxy 127.0.0.1:9101 {
	}`), "caddyfile")
